NodeVarValue = "str | tuple[str, str] | NodeVariable | dict"


def _normalize_node_var_to_dict(v: "NodeVarValue") -> dict:
    """Normalize a convenience node_var value to raw dict format."""
    if isinstance(v, str):
        return {"value": v, "type": "str"}
    if isinstance(v, tuple):
        return {"value": v[0], "type": v[1]}
    if isinstance(v, NodeVariable):
        return v.model_dump()
    if isinstance(v, dict):
        return v
    raise TypeError(f"Invalid node_var value: {v!r}")


def _set_node_vars_in_data(nodes_list: list[dict], parts: list[str], vars_dict: dict) -> None:
    """Find a node in raw data by path segments and merge vars into its execution_config."""
    name = parts[0]
    remaining = parts[1:]
    for node in nodes_list:
        if node.get("name") == name:
            if remaining:
                if node.get("type") != "subgraph":
                    raise KeyError(
                        f"Node '{name}' is not a subgraph, "
                        f"cannot traverse into '{'.'.join(remaining)}'"
                    )
                if node.get("path") is not None or node.get("nodes") is None:
                    full_path = '.'.join([name] + remaining)
                    raise ValueError(
                        f"Cannot set node_vars on '{full_path}': subgraph '{name}' "
                        f"is file-based (loads nodes from '{node.get('path')}'). "
                        f"File-based subgraph nodes are not available until resolution. "
                        f"To set variables on nodes inside this subgraph, either:\n"
                        f"  1. Set them as global_node_vars (applies to all nodes), or\n"
                        f"  2. Define the node_vars directly in the subgraph's config file, or\n"
                        f"  3. Convert the subgraph to an inline subgraph."
                    )
                _set_node_vars_in_data(node["nodes"], remaining, vars_dict)
                return
            else:
                node.setdefault("execution_config", {})
                existing = node["execution_config"].get("node_vars", {})
                unknown = set(vars_dict.keys()) - set(existing.keys())
                if unknown:
                    raise KeyError(
                        f"node_vars for node '{name}' contains variable names not declared "
                        f"in the node's config: {sorted(unknown)}. "
                        f"Declared variables: {sorted(existing.keys()) if existing else '(none)'}"
                    )
                node["execution_config"]["node_vars"] = {**existing, **vars_dict}
                return
    raise KeyError(f"Node '{name}' not found")

