def _default_pools() -> dict[str, "PoolConfig"]:
    """Create default pools with a main thread pool."""
    return {"main": PoolConfig(spec=MainPoolConfig())}


def _generate_default_output_queues(graph: "GraphConfig") -> dict[str, "OutputQueueConfig"]:
    """Generate output queues for all unconnected output ports.

    Creates one queue per unconnected output port with the naming convention
    "NODE_NAME::PORT_NAME".

    Args:
        graph: The resolved graph configuration.

    Returns:
        Dict mapping queue names to OutputQueueConfig objects.
    """
    # Collect all connected output ports (source of edges)
    connected_ports: set[tuple[str, str]] = set()
    for edge in graph.edges:
        source = edge.get_source()
        connected_ports.add((source.node_name, source.port_name))

    # Generate queues for unconnected output ports (excluding signal and control ports)
    queues: dict[str, OutputQueueConfig] = {}
    for node in graph.nodes:
        for port_name in node.out_ports:
            if (node.name, port_name) not in connected_ports and not is_signal_port(port_name) and not is_control_port(port_name):
                queue_name = f"{node.name}::{port_name}"
                queues[queue_name] = OutputQueueConfig(ports=[(node.name, port_name)])

    return queues


class NetConfig(VarResolvableModel):
    """Configuration for a Net."""
    model_config = {"arbitrary_types_allowed": True, "populate_by_name": True}

    project_root_override: str | VarRef | None = Field(default=None, description="Project root path override. Relative paths resolve from the config file's directory.")

    _file_path: Path | None = PrivateAttr(default=None)

    @property
    def project_root_path(self) -> Path:
        """Return the resolved project root as an absolute Path.

        Resolution order:
        - If project_root_override is set and absolute, return it directly.
        - If project_root_override is set and relative, resolve from _file_path.parent (or cwd).
        - If project_root_override is None and _file_path is set, return _file_path.parent.
        - If both are None, return cwd.
        """
        if self.project_root_override is not None:
            p = Path(self.project_root_override)
            if p.is_absolute():
                return p
            # Relative: resolve from config file dir or cwd
            base = self._file_path.parent if self._file_path is not None else Path(os.getcwd())
            return (base / p).resolve()
        if self._file_path is not None:
            return self._file_path.parent
        return Path(os.getcwd())

    @classmethod
    def from_file(
        cls,
        path: str | Path,
        *,
        keep_symlinks: bool = False,
        data_overrides: dict[str, Any] | None = None,
        global_node_vars: "dict[str, NodeVarValue] | None" = None,
        node_vars: "dict[str | tuple[str, ...], dict[str, NodeVarValue]] | None" = None,
    ) -> "NetConfig":
        """Load a NetConfig from a JSON or TOML file.

        Args:
            path: Path to the config file (.json or .toml).
            keep_symlinks: If True, don't resolve symlinks in the path.
            data_overrides: Shallow-merged into the raw file data before validation.
            global_node_vars: Convenience node_var values merged into net-level ``node_vars``.
            node_vars: Per-node node_var values. Keys are either a node name string
                or a tuple path for subgraph nodes (e.g. ``("subgraph", "inner_node")``).

        Returns:
            A NetConfig with _file_path set to the resolved absolute path.

        Raises:
            FileNotFoundError: If the file does not exist.
            ValueError: If the file extension is not .json or .toml.
        """
        path = Path(path).absolute() if keep_symlinks else Path(path).resolve()
        if not path.exists():
            raise FileNotFoundError(f"Config file not found: {path}")

        content = path.read_text()
        suffix = path.suffix.lower()

        if suffix == ".json":
            data = json.loads(content)
        elif suffix == ".toml":
            data = tomllib.loads(content)
        else:
            raise ValueError(f"Unsupported config file format: {suffix}. Use .json or .toml.")

        # 1. Shallow merge data_overrides
        if data_overrides:
            data = {**data, **data_overrides}

        # 2. Merge global_node_vars
        if global_node_vars:
            existing = data.get("node_vars") or {}
            unknown = set(global_node_vars.keys()) - set(existing.keys())
            if unknown:
                raise KeyError(
                    f"global_node_vars contains variable names not declared in the config file: "
                    f"{sorted(unknown)}. Declared variables: {sorted(existing.keys()) if existing else '(none)'}"
                )
            normalized = {k: _normalize_node_var_to_dict(v) for k, v in global_node_vars.items()}
            data["node_vars"] = {**existing, **normalized}

        # 3. Merge per-node vars
        if node_vars:
            for node_key, vars_for_node in node_vars.items():
                normalized = {k: _normalize_node_var_to_dict(v) for k, v in vars_for_node.items()}
                if isinstance(node_key, str):
                    parts = [node_key]
                else:
                    parts = list(node_key)
                _set_node_vars_in_data(data["graph"]["nodes"], parts, normalized)

        config = cls.model_validate(data)
        config._file_path = path
        return config

